use std::{collections::BTreeMap,fs};
fn main(){let root="/home/ubuntu/src/zopro-perf-work/bounded-gather-profile177";let mut counts:BTreeMap<u64,[u64;2]>=BTreeMap::new();for(arm,base,slot)in[("OFF",0x480f50,0),("ON",0x480810,1)]{for b in 0..3{let meta=fs::read_to_string(format!("{root}/run/metadata-cycles-{arm}-{b}/stdout.log")).unwrap();let line=meta.lines().find(|l|l.contains("PERF_RECORD_MMAP")&&l.contains("sdk-")&&l.contains("r-xp")).unwrap();let start=u64::from_str_radix(line.split("[0x").nth(1).unwrap().split("(").next().unwrap(),16).unwrap();let off=u64::from_str_radix(line.split("@ 0x").nth(1).unwrap().split_whitespace().next().unwrap(),16).unwrap();let bin=if arm=="OFF"{"control"}else{"candidate"};let elf=fs::read(format!("/home/ubuntu/src/zopro-perf-work/bounded-gather-sdk177/sdk-{bin}-znver4")).unwrap();let u64at=|i|u64::from_le_bytes(elf[i..i+8].try_into().unwrap());let ph=u64at(32)as usize;let ents=u16::from_le_bytes(elf[54..56].try_into().unwrap())as usize;let n=u16::from_le_bytes(elf[56..58].try_into().unwrap())as usize;let delta=(0..n).map(|i|ph+i*ents).find_map(|i|{let kind=u32::from_le_bytes(elf[i..i+4].try_into().unwrap());let flags=u32::from_le_bytes(elf[i+4..i+8].try_into().unwrap());if kind==1&&flags&1!=0{Some(u64at(i+16)-u64at(i+8))}else{None}}).unwrap();let bias=start-off-delta;let text=fs::read_to_string(format!("{root}/run/decode-cycles-{arm}-{b}/stdout.log")).unwrap();for line in text.lines(){let fields:Vec<_>=line.split_whitespace().collect();if fields.len()<6{continue;}if let Ok(ip)=u64::from_str_radix(fields[4].trim_start_matches("0x"),16){let ip=ip.wrapping_sub(bias);if(base..base+0xca96).contains(&ip){counts.entry(ip-base).or_default()[slot]+=1;}}}}}let asm:BTreeMap<u64,String>=fs::read_to_string(format!("{root}/g2-OFF.asm")).unwrap().lines().filter_map(|l|{let(a,b)=l.trim().split_once(':')?;let a=u64::from_str_radix(a,16).ok()?;Some((a-0x480f50,b.trim().to_owned()))}).collect();let mut rows:Vec<_>=counts.into_iter().collect();rows.sort_by_key(|(_,n)|std::cmp::Reverse(n[1]as i64-n[0]as i64));for(offset,n)in rows.into_iter().take(18){println!("+{offset:04x} OFF {:4} ON {:4} delta {:+5} {}",n[0],n[1],n[1]as i64-n[0]as i64,asm.get(&offset).map(String::as_str).unwrap_or("IP not instruction start"));}}
